INSERT INTO `tips` VALUES ('Spring','July, August, September','Pack light, breathable fabrics like cotton and linen. A light jacket or scarf is essential for mornings and evenings.\n Bring comfortable walking shoes or sneakers, as you\'ll likely be doing a lot of exploring.\n Even in spring, the sun can be strong. Pack sunscreen, sunglasses and a hat.\n A multi-purpose scarf can be used for modesty in temples, as a fashion accessory, or for warmth.\n Spring can bring unexpected showers, so a compact umbrella is a lifesaver.'),('Summer','July, August, September','Pack loose-fitting clothes made from cotton, linen, or other natural fibers to combat the heat and humidity.\n Carry a reusable water bottle to reduce plastic waste and stay hydrated in the extreme heat.\n Bring high-SPF sunscreen, a wide-brimmed hat, and sunglasses with UV protection.\n Pack a light cardigan or long-sleeved shirt for protection from powerful air conditioning in hotels and restaurants.\n Mosquitoes can be a problem, so bring a good insect repellent, especially if you\'re traveling to a tropical region.'),('Monsoon','July, August, September','Pack a waterproof jacket or raincoat and a bag with a rain cover. Use waterproof pouches for your phone, passport, and other valuables.\n Leave the jeans and heavy cotton at home. Pack synthetic fabrics that dry quickly to avoid feeling damp and uncomfortable.\n Pack sandals with a good grip or rubber shoes to navigate through wet and muddy streets.\n This is the breeding season for mosquitoes. Pack a strong repellent to protect against mosquito-borne diseases.\n Microfiber towels are highly absorbent and dry much faster than cotton towels, making them ideal for the monsoon.'),('Autumn','October, November','Pack a mix of light clothes for warm days and a few sweaters or a light jacket for cooler evenings.\n Bring comfortable walking shoes for sightseeing, as the weather is perfect for it.\n Don\'t forget sunscreen and sunglasses. The sun is still strong, and a hat is a good idea.\n A scarf or shawl can be used for warmth, sun protection, or to cover up when visiting religious sites.\n While not as hot as summer, it\'s still important to carry a reusable water bottle.'),('Winter','December, January, February','\n Pack thermals, sweaters, and a warm outer jacket.\n Wear your heaviest coat and boots on the plane to save luggage space and weight.\n A warm scarf, gloves, and a beanie or cap are crucial for staying warm, especially in Northern India.\n Pack heavy moisturizer, lip balm, and hand cream to combat the dry, cold air.\n A thermos for hot beverages is a game-changer for staying warm on cold days and nights.');
/*!40000 ALTER TABLE `tips` ENABLE KEYS */;
UNLOCK TABLES;

