INSERT INTO `travel_guide` VALUES (1.010,'Historical & Heritage','Karnataka','Explore Virupaksha Temple, Visit Vijaya Vittala Temple & its stone chariot, Watch sunset from Matanga Hill, Coracle ride on Tungabhadra River, Cycle or walk through Hampi ruins, Experience Hampi Bazaar','UNESCO World Heritage Site, Ruins of the Vijayanagara Empire, Intricate temples & architecture, Giant boulders and unique landscapes','Hampi','Oct-Feb','3,000 to 5,500'),(1.020,'Historical & Heritage','Uttar Pradesh','Visit Taj Mahal (UNESCO Heritage & Wonder of the World), Explore Agra Fort, Sunset view at Mehtab Bagh, Day trip to Fatehpur Sikri, Shop for marble handicrafts & leather goods, Taste Agra ka Patha','Taj Mahal (symbol of love), Fatehpur Sikri, Mughal architecture, Handicrafts & marble inlay work, Famous sweet \"Patha\"','Agra','Oct-Mar','3,500 to 6,000'),(1.030,'Historical & Heritage','Delhi','Visit Red Fort, Explore Jama Masjid, Street food at Chandni Chowk, Shop for spices at Khari Baoli, Rickshaw rides through narrow lanes, Visit Raj Ghat (Mahatma Gandhi?s memorial)','Mughal architecture, Heritage markets, Street food paradise','Old Delhi (Shahjahanabad)','Oct-Mar','2,500 to 6,000'),(1.040,'Historical & Heritage','Rajasthan','Visit Amber Fort & enjoy an elephant/jeep ride, Explore City Palace & Jantar Mantar, Shop at Johari Bazaar & Bapu Bazaar, Enjoy traditional Rajasthani cuisine, Hot air balloon ride for aerial views, Evening at Chokhi Dhani (ethnic village resort)','\"Pink City\" of India, Royal palaces & forts, Traditional Rajasthani art & handicrafts, Colorful festivals (Teej, Gangaur, Jaipur Literature Festival)','Jaipur','Oct-Mar','4,000 to 7,000'),(1.050,'Historical & Heritage','Madhya Pradesh','Explore Western Group of Temples (UNESCO site), Visit Kandariya Mahadeva Temple, Attend the Khajuraho Dance Festival, Sound & light show at temples, Visit Raneh Falls and Ken Gharial Sanctuary nearby, Shop for local handicrafts & sculptures','UNESCO World Heritage Site, Intricate temple carvings, Erotic sculptures & Nagara-style architecture, Blend of Hindu & Jain temples','Khajuraho Group of Monuments','Oct-Mar','3,000 to 5,500'),(1.060,'Historical & Heritage','Odisha','Visit the Konark Sun Temple (UNESCO site), Attend the Konark Dance Festival, Relax at Chandrabhaga Beach, Visit Archaeological Museum, Konark, Explore nearby Jagannath Temple, Shop for stone carvings & handicrafts','13th-century Sun Temple, Chariot-shaped architecture with stone wheels & horses, UNESCO World Heritage Site, Cultural & classical dance hub','Konark','Nov-Feb','3,000 to 5,500'),(1.070,'Historical & Heritage','Madhya Pradesh','Visit the Great Stupa of Sanchi (UNESCO site), Explore Ashoka Pillar, See Toranas (gateway sculptures), Visit the Sanchi Archaeological Museum, Take heritage walks around Buddhist monuments, Day trip to nearby Udayagiri Caves','Oldest stone structure in India, Buddhist architecture & art, Built by Emperor Ashoka (3rd century BCE), UNESCO World Heritage Site','Sanchi Stupa','Nov-Mar','3,000 to 5,000'),(1.080,'Historical & Heritage','Tamil Nadu','Visit the Shore Temple (UNESCO site), Explore Pancha Rathas (Five Rathas), Admire Arjuna?s Penance rock relief, Relax at Mahabalipuram Beach, See Krishna?s Butterball (giant boulder), Shop for stone carvings & handicrafts','Ancient Pallava dynasty rock-cut architecture, Seaside temples & monuments, UNESCO World Heritage Site (Group of Monuments), Beautiful beaches, Dravidian architecture','Mahabalipuram','Nov-Feb','4,000 to 7,000'),(1.090,'Historical & Heritage','Maharashtra','Explore the Ajanta Caves (ancient Buddhist rock-cut caves), Visit the Ellora Caves (Hindu, Jain & Buddhist temples), See the Kailasa Temple, Visit Grishneshwar Temple (Jyotirlinga), Shop for handicrafts & souvenirs in Aurangabad','UNESCO World Heritage Sites, Exquisite rock-cut architecture, Ancient Buddhist art & murals, World-famous monolithic Kailasa Temple','Aurangabad','Nov-Mar','3,500 to 6,000'),(1.100,'Historical & Heritage','Arunachal Pradesh','Visit Tawang Monastery (largest in India, 2nd largest in the world), See Sela Pass (snow-clad mountain pass), Explore Madhuri Lake (Shonga-tser Lake), Trekking & hiking in the Himalayas, Attend Torgya Festival, Visit Bumla Pass (Indo-China border)','Scenic Himalayan landscapes, Tibetan Buddhist culture, Monasteries & festivals, Adventure & snow experiences','Tawang','Mar-Oct','3,500 to 6,000'),(1.110,'Historical & Heritage','Tripura','Explore the grand palace architecture, Visit the Tripura State Museum inside the palace, Walk through Mughal-style gardens & ponds, Attend cultural events, Photography of royal heritage','Iconic royal palace of Tripura, Blend of Mughal, Roman & British architecture, Houses museum showcasing Tripuri history, culture & tribal traditions','Agartala','Oct-Mar','3,000 to 5,000'),(2.010,'Pilgrimage','Uttar Pradesh','Witness the Ganga Aarti at Dashashwamedh Ghat, Take a boat ride on the Ganges at sunrise, Visit Kashi Vishwanath Temple, Explore narrow lanes & markets, Visit Sarnath (Buddhist pilgrimage site), Taste local delicacies','One of the oldest living cities in the world, Spiritual & cultural hub of India, Ghats of the Ganges, Silk weaving & Banarasi sarees','Varanasi','Oct-Nov','3,000 to 5,500'),(2.020,'Pilgrimage','Tamil Nadu','Visit the Ramanathaswamy Temple, Walk on the Pamban Bridge (India?s first sea bridge), Explore Dhanushkodi (Ghost Town & Beach), Visit APJ Abdul Kalam Memorial, Take part in pilgrimage rituals & sea dips, Relax at Ariyaman Beach','One of the Char Dham pilgrimage sites, Sacred temple town linked to Lord Rama, Engineering marvel Pamban Bridge, Spirituality + coastal beauty','Rameshwaram','Oct-Mar','4,500 to 7,000'),(2.030,'Pilgrimage','Punjab','Visit the Golden Temple and take part in prayers, Experience the Langar (community kitchen), Walk around the Amrit Sarovar (holy lake), Visit the Akal Takht (seat of Sikh authority), Enjoy the night view when the temple glows in golden lights','Holiest shrine of Sikhism, Gold-covered sanctum in the middle of a sacred pool, Symbol of equality, service & spirituality, World?s largest free kitchen -Langar','Golden Temple','Oct-Mar','3,000 to 5,500'),(2.040,'Pilgrimage','Jammu & Kashmir','Undertake the 13 km trek from Katra to the temple cave, Visit the holy cave shrine of Mata Vaishno Devi, Experience Ardh Kuwari Cave, Use helicopter rides, ponies or palkis for easier access, Shop for religious souvenirs & prasad in Katra','One of the holiest Hindu pilgrimage sites, Sacred cave dedicated to Goddess Vaishno Devi, Pilgrimage of faith & devotion with millions of visitors yearly','Vaishno Devi Temple','Mar-Oct','3,500 to 6,000'),(2.050,'Pilgrimage','Tamil Nadu','Visit the magnificent Meenakshi Amman Temple(one of the largest temple complexes in India), Explore the Thirumalai Nayakkar Mahal, Stroll through the Gandhi Memorial Museum, Witness the evening temple ceremonies & processions','Ancient temple city, over 2,500 years old, Rich Dravidian culture & architecture,- Meenakshi Temple (dedicated to Goddess Meenakshi & Lord Sundareswarar), Center of Tamil heritage','Madurai','Oct-Mar','3,000 to 5,500'),(2.060,'Pilgrimage','Uttarakhand','Undertake the 16 km trek from Gaurikund to Kedarnath Temple, Visit the sacred Kedarnath Temple (one of the 12 Jyotirlingas), Explore Adi Shankaracharya Samadhi, Enjoy views of Mandakini River & snow-capped peaks, Trek to Vasuki Tal','One of the Char Dham pilgrimage sites, Kedarnath Temple dedicated to Lord Shiva, Surrounded by the Himalayas at 3,583 m altitude, Spirituality + adventure trekking','Kedarnath','May-Jun, Sep-Oct','4,500 to 8,000'),(2.070,'Pilgrimage','Uttarakhand','Visit the sacred Badrinath Temple, Take a holy dip at Tapt Kund, Explore Mana Village (last Indian village before Tibet border), Visit Vyas Gufa & Ganesh Gufa (mythological caves), Trek to Vasudhara Falls, Scenic views of Neelkanth Peak','Major Char Dham pilgrimage site, Ancient temple with strong mythological links, High-altitude Himalayan spirituality, Culturally significant border village (Mana)','Badrinath','May-Jun, Sep-Oct','4,500 to 8,000'),(2.080,'Pilgrimage','Andhra Pradesh','Visit the sacred Sri Venkateswara Temple, Explore Kapila Theertham Waterfall & Temple, Visit Sri Padmavathi Ammavari Temple, Wildlife spotting at Sri Venkateswara National Park, Climb the Alipiri Steps for a spiritual trek','One of the richest & most visited temples in the world, Dedicated to Lord Venkateswara (form of Vishnu), Famous Tirupati Laddus prasadam, Spiritual significance for Hindus globally','Tirupati','Sep-Feb','3,500 to 6,500'),(2.090,'Pilgrimage','Odisha','Visit the famous Jagannath Temple (one of the Char Dham pilgrimage sites), Witness the Rath Yatra festival, Relax at Puri Beach, Visit Chilika Lake for birdwatching & dolphin spotting, Explore Konark Sun Temple','Jagannath Temple (dedicated to Lord Jagannath, form of Vishnu), Annual Rath Yatra (Chariot Festival), Scenic beaches & spiritual vibe, Rich Odisha art & culture','Puri','Oct-Feb','3,000 to 5,500'),(2.100,'Pilgrimage','Gujarat','Visit the sacred Dwarkadhish Temple, Explore Bet Island, Take a dip at the holy Gomti River, Visit Rukmini Devi Temple, See the Dwarka Lighthouse & Dwarka Beach, Attend Janmashtami celebrations','Dwarkadhish Temple (legendary kingdom of Lord Krishna), One of the Char Dham pilgrimage sites, Mythological & historical significance, Coastal town with serene beaches','Dwarka','Oct-Mar','3,000 to 4,000'),(2.110,'Pilgrimage','Maharashtra','Visit the Sai Baba Samadhi Mandir, Attend the Kakad Aarti & Shej Aarti, Explore Dwarkamai Mosque (where Sai Baba lived), Visit Chavadi (associated with Sai Baba?s life), Visit Shani Shingnapur','Worldwide pilgrimage center dedicated to Sai Baba of Shirdi, Known for spiritual teachings of faith, humanity & devotion, Daily attracts thousands of devotees, Symbol of religious harmony','Ahmednagar','Oct-Mar','3,000 to 5,500'),(2.120,'Pilgrimage','Gujarat','Visit the magnificent Somnath Jyotirlinga Temple and the Triveni Sangam Ghat (meeting point of 3 rivers), Explore Somnath Beach and  Bhalka Tirth (where Lord Krishna  left his earthly body), See Junagadh Gate & Prabhas Patan Museum','First of the 12 Jyotirlingas of Lord Shiva, Ancient temple with history of repeated destruction & reconstruction, Symbol of faith, resilience, and cultural heritage, Scenic coastal location','Prabhas Patan','Oct-Feb','3,000 to 5,500'),(2.130,'Pilgrimage','Mizoram','Visit the grand white-marble Solomon\'s Temple, Explore the surrounding landscaped gardens, Learn about Mizoram\'s strong Christian heritage, Photography of the impressive architecture','One of the largest churches in Mizoram, Important Christian pilgrimage site, Unique architectural style resembling biblical Solomon\'s Temple, Center of faith & community life in Aizawl','Aizawl','Oct-Mar','3,000 to 5,000'),(2.140,'Pilgrimage','Assam','Visit the sacred Kamakhya Temple (one of the 51 Shakti Peethas), Participate in Ambubachi Mela, Explore Nilachal Hill for panoramic views of Guwahati, Experience Assamese culture & cuisine','Ancient temple dedicated to Goddess Kamakhya, Major Shakti Peetha with strong mythological significance, Annual Ambubachi Mela attracts thousands of pilgrims, Blend of spirituality, culture & tradition','Guwahati','Oct-Mar','3,000 to 5,500'),(3.010,'Hill Station','Himachal Pradesh','Visit Khajjiar (Mini Switzerland of India), Trekking & nature walks in Dainkund Peak, Boating at Chamera Lake, Explore St. John?s Church & colonial architecture, Shopping at Tibetan Market, Relax amidst pine-clad valleys & waterfalls','Hill station charm, Snow-capped Himalayan views, Colonial-era architecture, Peaceful nature retreat','Dalhousie','Mar-Jun, Dec-Feb','3,500 to 6,000'),(3.020,'Hill Station','Himachal Pradesh','Stroll along The Mall Road & Ridge, Visit Jakhoo Temple (dedicated to Lord Hanuman), Ride the Kalka?Shimla Toy Train (UNESCO site), Visit Christ Church & colonial architecture, Day trips to Kufri & Chail, Adventure sports: skiing, ice skating, trekking','Popular hill station, Summer capital of British India, Scenic pine forests & snow-clad mountains, Colonial heritage','Shimla','Mar-Jun, Oct-Dec','3,500 to 6,000'),(3.030,'Hill Station','Himachal Pradesh','Adventure sports: paragliding, river rafting, skiing, trekking, Visit Solang Valley & Rohtang Pass, Explore Hidimba Devi Temple, Relax at Vashisht Hot Springs, Shopping & cafes at Old Manali & Mall Road, Visit Naggar Castle & nearby villages','Adventure capital of Himachal, Snow-capped mountains & valleys, Honeymoon & backpacker hub, Gateway to Leh?Ladakh road trips','Manali','Oct-Jun, Dec-Feb','4,000 to 7,000'),(3.040,'Hill Station','West Bengal','Ride the Darjeeling Himalayan Railway (Toy Train - UNESCO site), Watch sunrise at Tiger Hill with views of Kanchenjunga, Visit Batasia Loop & War Memorial, Explore Tea Estates & Tea Museum, Visit Padmaja Naidu Himalayan Zoological Park','World-famous Darjeeling Tea, Scenic Himalayan views, Colonial-era charm, UNESCO toy train','Darjeeling','Mar-Jun, Sep-Nov','3,500 to 6,000'),(3.050,'Hill Station','Kerala','Visit sprawling tea plantations & Tea Museum, Trek to Anamudi Peak (highest in South India), Explore Eravikulam National Park (Nilgiri Tahr wildlife), Relax at Mattupetty Dam & Lake, Visit Top Station for panoramic views, Enjoy spice gardens & waterfalls','Hill station charm, Lush tea estates & greenery, Wildlife (Nilgiri Tahr), Cool climate year-round','Munnar','Sep-Mar','3,500 to 6,000'),(3.060,'Hill Station','Tamil Nadu','Ride the Nilgiri Mountain Railway (Toy Train - UNESCO site), Visit Ooty Botanical Gardens & Rose Garden, Boat ride at Ooty Lake, Trekking in Doddabetta Peak, Visit Tea plantations & factories, Day trips to Coonoor & Avalanche Lake','Popular hill station of South India, Tea estates & lush green valleys, Pleasant climate & colonial charm, Nilgiri Hills & scenic landscapes','Ooty','Mar-Jun','3,500 to 6,000'),(3.070,'Hill Station','Uttarakhand','Boating at Naini Lake, Visit Naina Devi Temple, Enjoy scenic views from Snow View Point & Tiffin Top, Explore The Mall Road (shopping & eateries), Visit Nainital Zoo, Day trips to Bhimtal, Sattal, and Naukuchiatal lakes','\"Lake District of India\", Scenic Himalayan lake views, Pleasant hill station climate, Boating & nature walks','Nainital','Mar-Jun, Sep-Nov','3,000 to 5,500'),(3.080,'Hill Station','Uttarakhand','Stroll on Mall Road for shopping & cafes, Ropeway ride to Gun Hill, Visit Kempty Falls & Company Garden, Trek to Lal Tibba (highest point), Explore Camel?s Back Road, Day trips to nearby Dhanaulti','\"Queen of Hills\", Colonial-era charm, Himalayan views, Waterfalls & trekking','Mussoorie','Apr-Jun, Sep-Nov','3,000 to 5,500'),(3.090,'Hill Station','Karnataka','Visit Abbey Falls & Iruppu Falls, Coffee plantation tours, Trekking at Tadiandamol Peak, Explore Dubare Elephant Camp, Visit Talacauvery (origin of River Kaveri), Enjoy local Kodava cuisine','\"Scotland of India\", Coffee plantations & lush greenery, Waterfalls & trekking, Rich Kodava culture','Coorg','Oct-Mar','3,000 to 6,000'),(3.100,'Hill Station','Rajasthan','Visit Dilwara Jain Temples (marble architecture), Boating at Nakki Lake, Sunset view from Sunset Point & Honeymoon Point, Trekking & nature walks in Mount Abu Wildlife Sanctuary, Explore Achalgarh Fort, Shopping for Rajasthani handicrafts','Only hill station of Rajasthan, Jain temples with intricate marble carvings, Scenic Aravalli Hills, Cool retreat in the desert state','Mount Abu','Oct-Mar','3,000 to 5,500'),(3.110,'Hill Station','Jammu & Kashmir','Ride the Gulmarg Gondola, Skiing, snowboarding & winter sports, Trekking & nature walks in summer, Visit Alpather Lake, Play golf at Gulmarg Golf Course, Enjoy snow views of Apharwat Peak','\"Meadow of Flowers\", Snow-capped peaks & adventure sports, Skiing hub of India, Picturesque landscapes in every season','Gulmarg','Dec-Feb, Apr-Jun','4,000 to 7,500'),(3.120,'Hill Station','Meghalaya','Visit Elephant Falls & Shillong Peak, Explore Ward/\'s Lake & Lady Hydari Park, Experience Umiam Lake boating, Don Bosco Museum, Shopping at Police Bazaar, Enjoy music cafes & festivals','\"Scotland of the East\", Pleasant climate & rolling hills, Rich Khasi culture & music scene, Scenic waterfalls & lakes','Shillong','Sep-Mar','3,000 to 6,000'),(4.010,'Beach','Andaman & Nicobar Islands','Visit Radhanagar Beach (Havelock Island, one of Asia?s best beaches), Snorkeling & scuba diving at Neil Island & North Bay, Visit Cellular Jail, Explore Ross Island ruins, Witness bioluminescence at Havelock beaches, Visit Baratang Island','Stunning beaches & coral reefs, Cellular Jail (freedom struggle history), Rich marine life & adventure sports, Tribal cultures (restricted areas), Remote island charm','Andaman & Nicobar Islands','Nov-Apr','4,500 to 8,000'),(4.020,'Beach','Kerala','Relax at the scenic Varkala Beach (Papanasam Beach), Enjoy the cliffside cafés & yoga retreats, Visit the Janardanaswamy Temple, Paragliding & beachside adventures, Explore Anjengo Fort & backwaters nearby','Famous for its unique cliff overlooking the Arabian Sea, Spiritual & wellness tourism hub, Blend of beaches, yoga, Ayurveda, and temples, Less crowded alternative to Kovalam','Varkala','Nov-Mar','3,000 to 5,500'),(4.030,'Beach','Tamil Nadu','Take a walk along the 13 km stretch, Visit statues & memorials (MGR, Anna, Gandhi, Kannagi), Relax at the Marina Lighthouse for panoramic city views, Explore San Thome Basilica & Kapaleeshwarar Temple, Enjoy kite flying & beach photography','Longest natural urban beach in India, Cultural landmark of Chennai, Hub for street food, evening leisure & political history, Bustling crowds and lively atmosphere','Marina Beach','Nov-Feb','3,000 to 5,000'),(4.040,'Beach','Kerala','Relax at Lighthouse Beach, Hawa Beach & Samudra Beach, Climb the Vizhinjam Lighthouse for panoramic views, Enjoy surfing & parasailing, Try Kerala seafood delicacies at beachfront shacks, Explore nearby Vizhinjam Rock Cut Cave Temple','One of India\'s most famous beach destinations, Known for crescent-shaped coastline & lighthouse, Popular for water sports & Ayurveda, Major tourist hub since the 1930s','Kovalam','Sep-Mar','3,000 to 5,500'),(4.050,'Beach','Karnataka','Relax on the Om-shaped shoreline, Try water sports (banana boat rides, parasailing, jet skiing, surfing), Trek to nearby beaches like Half Moon Beach & Paradise Beach, Visit nearby Gokarna temples (like Mahabaleshwar Temple)','Famous for its natural Om shape coastline, A mix of spirituality & beach tourism, Less commercialized than Goa, Popular with both Indian & international backpackers','Om Beach','Oct-Mar','3,000 to 5,500'),(4.060,'Beach','Dadra & Nagar Haveli and Daman & Diu','Relax at Nagoa Beach, Ghoghla Beach & Chakratirth Beach, Explore Diu Fort & Panikhota Fort (Portuguese legacy), Visit St. Paul?s Church, Adventure sports like parasailing, surfing, scuba diving, Walk through Naida Caves, Explore INS Khukri Memorial','Blend of Portuguese history & Indian culture, Beaches, forts, and churches, A peaceful alternative to Goa, Unique limestone caves & coastal beauty','Diu','Oct-Feb','3,000 to 5,500'),(4.070,'Beach','West Bengal','Relax on one of India\'s longest drivable beaches, Adventure activities like ATV rides, jet skiing, banana boat rides, parasailing, Beach walks & sunset views, Enjoy fresh Bengali seafood at beach, Visit  Tajpur & Shankarpur beaches','Known as a peaceful beach destination near Kolkata, Famous for its clean, long stretch of drivable sand, Quieter and less crowded than Digha, Popular weekend getaway for families & couples','Mandarmani Beach','Nov-Feb','3,000 to 5,000'),(4.080,'Beach','Odisha','Enjoy a walk along the golden sandy shoreline, Experience the annual Puri Beach Festival with sand art & cultural shows, Try local seafood delicacies, Horse & camel rides for tourists, Visit nearby Jagannath Temple & Konark Sun Temple','Famous for its golden sand & waves of the Bay of Bengal, Sand art by Sudarsan Pattnaik, world-famous sand artist, Cultural festivals & religious significance (close to Jagannath Temple), Popular destination for pilgrims & leisure travelers alike','Puri Beach','Nov-Feb','3,000 to 5,000'),(4.090,'Beach','Goa','Relax at Baga, Anjuna & Palolem Beaches, Water sports (parasailing, jet skiing, scuba diving), Visit Basilica of Bom Jesus & Portuguese churches, Explore Dudhsagar Waterfalls, Night markets & beach parties','Beaches & nightlife, Portuguese heritage & churches, Seafood & beach shacks, Adventure & water sports','Goa','Nov-Feb','3,500 to 6,500'),(4.100,'Beach','Puducherry','Stroll along Promenade Beach & Paradise Beach, Visit Auroville & Aurobindo Ashram, Explore French Quarter with colonial architecture, Café hopping & shopping, Visit Basilica of the Sacred Heart of Jesus & Manakula Vinayagar Temple','French colonial charm, Serene beaches & spiritual centers, Blend of Indian & French culture, Yoga & wellness retreats, Popular coastal getaway','Puducherry','Oct-Mar','3,000 to 6,000'),(5.010,'Lake & Backwater','Kerala','Houseboat cruise, Explore Kumarakom Bird Sanctuary, Canoe ride in village canals, Ayurvedic spa & wellness retreats, Taste traditional Kerala cuisine (fish curry, appam, sadya)','Serene backwaters & houseboats, Lush greenery & coconut palms, Ayurvedic treatments, Authentic Kerala lifestyle','Alappuzha','Nov-Feb','3,000 to 5,000'),(5.020,'Lake & Backwater','Rajasthan','Boat ride on Lake Pichola, Visit the majestic City Palace, Explore Jagdish Temple, Fateh Sagar Lake, See Saheliyon ki Bari (Garden of Maidens), Visit Bagore ki Haveli for cultural shows, Visit Monsoon Palace (Sajjangarh Fort) for sunset views','Called the \"City of Lakes\", Romantic palaces & royal heritage, Famous for destination weddings, Blend of Rajput architecture & Mewar culture','Udaipur','Oct-Mar','4,000 to 5,000'),(5.030,'Lake & Backwater','Jammu & Kashmir','Take a Shikara ride o